    }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}();
        uint256 beforeBalance = c.balances(address(this));
        uint256 beforeContractEther = address(c).balance;
        uint256 beforeTestEther = address(this).balance;

        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balances(address(this));
        uint256 afterContractEther = address(c).balance;
        uint256 afterTestEther = address(this).balance;

        if (withdrawAmount <= beforeBalance) {
            assert(!reverted);
            assert(afterBalance == beforeBalance - withdrawAmount);
            assert(afterContractEther == beforeContractEther - withdrawAmount);
            assert(afterTestEther == beforeTestEther + withdrawAmount);
        } else {
            assert(reverted);
            assert(afterBalance == beforeBalance);
            assert(afterContractEther == beforeContractEther);
            assert(afterTestEther == beforeTestEther);
        }
    }

    receive() external payable {}
}

