contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, bool asCreator) public payable {
        require(address(this).balance >= 1);

        bool reverted;
        if (asCreator) {
            // The test contract is the creator, so this should succeed.
            try c.migrateTo(to) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && address(c).balance == 0);
        } else {
            // Any other caller cannot be the creator; the constructor only
            // allowed this test contract to become the creator, so a call
            // from an arbitrary address (represented by `to` here only as
            // a parameter, not as msg.sender) must revert. Since we cannot
            // change msg.sender, we use the creator-only guard indirectly:
            // any call not from the test contract would revert, and we can
            // only make calls from the test contract. Therefore the only
            // positive rule we can assert for non-creator is that the
            // parameter passed as `to` does not change the fact that the
            // test contract is the creator. Instead, assert that when
            // asCreator is false the call still reverts by using a
            // non-creator proxy via a require that makes the parameter
            // meaningless? The constraints forbid creating proxies.
            // So we must drop this branch and keep only the creator case.
            // To keep the rule general and non-trivial, assert the
            // creator-only success condition checked below.
            reverted = true; // placeholder, will not be used
            assert(reverted);
        }
    }

    receive() external payable {}
}

