    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address to) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}();

        uint256 beforeBal = address(c).balance;
        require(beforeBal == amount);

        bool migrated;
        try c.migrateTo(to) {
            migrated = true;
        } catch {
            migrated = false;
        }

        assert(migrated && address(c).balance == 0 && beforeBal == amount);
    }

    receive() external payable {}
}

