contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool isMax = (amount == type(uint256).max);

        assert(
            (isMax && reverted) ||
            (!isMax && (
                (reverted && address(c).balance == balBefore) ||
                (!reverted && address(c).balance == balBefore + amount)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        uint256 balBefore = address(c).balance;
        bool reverted;

        if (amount == type(uint256).max) {
            try c.deposit{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && address(c).balance == balBefore);
        } else {
            // amount is not max, so balances[msg.sender] + amount cannot overflow
            try c.deposit{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && address(c).balance == balBefore + amount);
        }
    }

    receive() external payable {}
}

