contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 d, uint256 a) public payable {
        require(d > 0 && d <= address(this).balance);

        uint256 balBeforeDeposit = address(c).balance;
        uint256 testBalBeforeDeposit = address(this).balance;

        c.deposit{value: d}();

        uint256 balBeforeWithdraw = address(c).balance;
        uint256 testBalBeforeWithdraw = address(this).balance;

        bool reverted;
        try c.withdraw(a) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (a > d) {
            assert(reverted);
            assert(address(c).balance == balBeforeWithdraw);
            assert(address(this).balance == testBalBeforeWithdraw);
        } else {
            assert(!reverted);
            assert(address(c).balance == balBeforeWithdraw - a);
            assert(address(this).balance == testBalBeforeWithdraw + a);
        }
    }

    receive() external payable {}
}

