contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to) public payable {
        require(to != address(c));
        uint256 balanceBefore = address(c).balance;

        // Setup: fund c so migrateTo has Ether to move.
        c.deposit{value: 1}();
        uint256 fundedBalance = address(c).balance;

        // Deciding call as its own top-level statement.
        bool reverted;
        try c.migrateTo(to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool selfTransfer = (to == address(this));
        if (selfTransfer) {
            assert(reverted && address(c).balance == fundedBalance);
        } else {
            assert(!reverted && address(c).balance == 0 && fundedBalance > 0);
        }
    }

    receive() external payable {}
}

