contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        uint256 preBalance = address(c).balance;
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool shouldRevert = (amount == 0) || (c.balances(address(this)) + amount < c.balances(address(this)));
        assert(reverted == shouldRevert);
        if (!reverted) {
            assert(address(c).balance == preBalance + amount);
        } else {
            assert(address(c).balance == preBalance);
        }
    }

    receive() external payable {}

    fallback() external payable {}
}
